package vn.rtr.aeris.native98;
import java.nio.file.*;import java.util.*;
public final class UnifiedReplay98{public static void main(String[]args)throws Exception{List<String>lines=Files.readAllLines(Paths.get(args[0]));List<byte[]>items=new ArrayList<>();for(String l:lines)if(l.startsWith("ITEM\t"))items.add(DirectTransport95.unhex(l.split("\t")[1]));UnifiedCore98 u=new UnifiedCore98(items.toArray(new byte[0][]),"00000000-0000-4000-8000-000000000098");int rx=0,tx=0,arm=0;long last=0;boolean sawArmed=false;for(String l:lines){String[]p=l.split("\t");if(p[0].equals("ITEM"))continue;last=Long.parseLong(p[1]);try{if(p[0].equals("RX")){u.receive(DirectTransport95.unhex(p[2]),last);rx++;sawArmed|=(Boolean)u.payload.snapshot(last).get("apArmed");}if(p[0].equals("TX")){u.flightApprove(u.wire(DirectTransport95.unhex(p[2])),last);tx++;}if(p[0].equals("GRANT")){u.flight.grant(last);arm++;}}catch(Exception e){throw new AssertionError("row "+rx+"/"+tx+" "+p[0]+" at "+last,e);}}if(!sawArmed||!u.flight.safeComplete(last))throw new AssertionError("NO_OBSERVED_COMPLETE");System.out.println("{\"status\":\"PASS\",\"rx\":"+rx+",\"tx\":"+tx+",\"grant\":"+arm+",\"payloadAllowsOnlyNativeAuthorizedArmed\":true,\"flightComplete\":true,\"scope\":\"REPLAY_PRIOR_AP_CAPTURE_NOT_NEW_SITL\"}");}}
